export type JsonObject = Record<string, unknown>;
export type CLIArgs = JsonObject & {
    _: string[];
    help?: boolean;
    apiUrl?: string;
    orgId?: string;
    noOpen?: boolean;
    noReport?: boolean;
    noAutoActions?: boolean;
    fullScan?: boolean;
    includeSensitive?: boolean;
    deviceName?: string;
    repo?: string;
    workspace?: string;
    path?: string | string[];
    task?: string | string[];
    entity?: string | string[];
    title?: string;
    claim?: string;
    kind?: string;
    ruleId?: string;
    outcome?: string;
    note?: string;
    adopted?: string;
    confidence?: string;
    correctTitle?: string;
    correctClaim?: string;
    correctKind?: string;
    correctPath?: string | string[];
    correctTask?: string | string[];
    correctEntity?: string | string[];
    branch?: string;
    tag?: string;
    commit?: string;
    userId?: string;
    teamId?: string;
    templateId?: string;
    limit?: string;
    json?: string;
    data?: string;
    guide?: string;
    params?: string;
    actionId?: string;
    manifestHash?: string;
    type?: string;
    evidenceType?: string;
    evidenceRef?: string;
    evidence?: string | string[];
};
export type AgentAction = {
    id: string;
    type: string;
    repo?: string | null;
    payload?: {
        manifest_url?: string;
        manifest_hash?: string;
        [key: string]: unknown;
    };
};
export type AgentCapabilities = {
    installation_id: string;
    skills: Record<string, {
        sha256: string | null;
    }>;
};
export type RepoScanResult = {
    schema_version: 1 | 2;
    scan_mode?: 'compact' | 'full';
    scanned_at: string;
    branch: string | null;
    commit: string | null;
    known_paths: string[];
    known_path_count?: number;
    known_path_sample?: string[];
    known_dirs?: string[];
    changed_paths: string[];
    deleted_paths: string[];
    renamed_paths: Array<{
        from: string;
        to: string;
    }>;
    code_entities: unknown[];
    code_entity_count?: number;
    code_entity_sample?: unknown[];
    repo_profile?: unknown;
    repo_brief?: string;
    agent_repo_guide?: unknown;
};
export type SkillManifestItem = {
    name: string;
    path: string;
    url?: string;
    sha256: string;
};
export type SkillManifest = {
    schema_version?: number;
    generated_at?: string;
    manifest_hash: string;
    skills: SkillManifestItem[];
};
